/* ---------- Automation canvas ---------- */
.acx{display:flex;flex-direction:column;gap:10px;width:100%}
.acx-top{display:flex;align-items:center;gap:8px;font-size:13px;flex-wrap:wrap}
.acx-name{font-weight:500}
.acx-sp{flex:1}
.acx-st{font-size:12.5px}
/* the canvas reads as a workflow editor: a dot every 16px, fading toward the edges so the steps sit in the middle of it */
.acx-cv{position:relative;height:300px;border-radius:18px;overflow:hidden;background-color:var(--chip);background-image:radial-gradient(ellipse at center,transparent 55%,var(--chip) 100%),radial-gradient(circle at 8px 8px,color-mix(in srgb,var(--fg) 20%,transparent) 1.1px,transparent 1.6px);background-size:100% 100%,16px 16px;background-position:0 0,center}
.acx-svg{position:absolute;inset:0;width:100%;height:100%}
.acx-svg path{fill:none;stroke:var(--faint);stroke-width:1.5;transition:stroke .6s var(--ease)}
/* on arrival the wires draw in after the steps have landed */
.acx-svg.intro path{stroke-dasharray:var(--l);animation:acxdraw .8s var(--ease) .42s backwards}
@keyframes acxdraw{from{stroke-dashoffset:var(--l)}}
/* a test run passes along each wire as one soft light, and the wire stays lightly lit once it has passed */
.acx-svg path.done{stroke:color-mix(in srgb,var(--accent) 32%,var(--faint))}
.acx-svg path.pulse{stroke:var(--accent);stroke-width:2.5;stroke-linecap:round;transition:none}
/* the steps fade in without moving, so the wires meet them exactly while they arrive */
.acx-in{animation:acxin .56s var(--ease) backwards}
@keyframes acxin{from{opacity:0;filter:blur(4px)}}
/* a step's badge pops in once; after that its spinner turns into a check with a short crossfade */
.acx-n .s{animation:acxs .34s cubic-bezier(.34,1.4,.64,1)}
@keyframes acxs{from{opacity:0;transform:scale(.6)}}
.acx-sv{display:grid;animation:acxsv .3s var(--ease)}
@keyframes acxsv{from{opacity:0;filter:blur(2px)}}
.acx-n{position:absolute;width:176px;padding:10px 12px;border-radius:14px;background:var(--surface);box-shadow:var(--shadow);display:flex;align-items:center;gap:10px;font-size:12.5px;text-align:left;transition:box-shadow .3s,left .5s var(--ease),top .5s var(--ease)}
.acx-n:hover{box-shadow:var(--shadow-pop)}
.acx-n{cursor:grab;touch-action:none;user-select:none}
.acx-n.drag{cursor:grabbing;transition:box-shadow .3s;box-shadow:var(--shadow-pop);z-index:3;transform:scale(1.02)}
.acx-n.sel{box-shadow:0 0 0 1px var(--rail),var(--shadow-pop)}
.acx-n .ic{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;flex:none}
.acx-n .t{display:flex;flex-direction:column;min-width:0}
.acx-n .t b{font-weight:500;font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.acx-n .t span{font-size:11.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.acx-n .s{position:absolute;right:-6px;top:-6px;width:18px;height:18px;border-radius:50%;display:grid;place-items:center;background:var(--surface);box-shadow:0 0 0 1px var(--line)}
.acx-n.run{box-shadow:0 0 0 1.5px color-mix(in srgb,var(--accent) 55%,transparent),0 0 0 6px color-mix(in srgb,var(--accent) 8%,transparent),var(--shadow)}
.acx-pop{width:240px;padding:12px}
.acx-pop h4{margin:0 0 10px;font-size:13px;font-weight:500}
.acx-fl{display:flex;flex-direction:column;gap:4px;margin-bottom:10px;font-size:12px;color:var(--muted)}
.acx-dd{display:flex;align-items:center;justify-content:space-between;height:32px;padding:0 10px;border-radius:9px;background:var(--accent-bg);color:var(--accent);font-size:13px;font-weight:500}
.acx-opts{display:none;flex-direction:column;padding:4px;border-radius:10px;background:var(--surface);box-shadow:var(--shadow-pop);margin-top:4px}
.acx-opts.open{display:flex}
.acx-opts .mi{font-size:12.5px;padding:6px 8px}
@media (max-width:720px){.acx-cv{height:420px}}

DM.def('automation-canvas', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{play}', I('play','xs'));
  const N = [
    { id:'t', ic:'clock', col:'var(--py)', t:'Schedule', d:'Mondays 9:00', y:.5, f:['When', ['Mondays 9:00','Every weekday','On new Figma version']] },
    { id:'a', ic:'figma', col:'var(--pl)', t:'Read frames', d:'Pricing, Checkout', y:.28, f:['Frames', ['Pricing, Checkout','All frames','Changed this week']] },
    { id:'b', ic:'spark', col:'var(--accent)', t:'Agent: audit', d:'Contrast, tokens', y:.72, f:['Checks', ['Contrast, tokens','Everything','Accessibility only']] },
    { id:'c', ic:'send', col:'var(--pm)', t:'Post summary', d:'#design in Slack', y:.5, f:['Channel', ['#design in Slack','Email the team','Linear ticket']] }
  ];
  const E = [['t','a'],['t','b'],['a','c'],['b','c']];
  const cv = $('.acx-cv', r), svg = $('.acx-svg', r), nodes = $('.acx-nodes', r), pop = $('.acx-pop', r), st = $('.acx-st', r);
  const narrow = () => cv.clientWidth < 560;
  // wide: the trigger and the last step sit the same distance in from each side and the two middle steps halfway between,
  // so the wires on the left and right are the same length at any width. A step you dragged keeps where you put it
  const wide = (n, W, w) => { const pad = Math.max(20, W * .06); return { x:{ t:pad + w / 2, a:W / 2, b:W / 2, c:W - pad - w / 2 }[n.id] / W, y:n.y }; };
  const pos = (n, W, w) => (narrow() ? n.um : n.uw) || (narrow() ? { x:{ t:.5, a:.28, b:.72, c:.5 }[n.id], y:{ t:.13, a:.42, b:.62, c:.88 }[n.id] } : wide(n, W, w));
  nodes.innerHTML = N.map(n => `<button class="acx-n" data-id="${n.id}"><span class="ic" style="color:${n.col};background:color-mix(in srgb,${n.col} 14%,transparent)">${I(n.ic,'xs')}</span><span class="t"><b>${n.t}</b><span class="d">${n.d}</span></span></button>`).join('');
  const el = id => $(`.acx-n[data-id="${id}"]`, nodes);
  function layout(){
    const W = cv.clientWidth, H = cv.clientHeight, small = narrow() || W < 700;
    $$('.acx-n', nodes).forEach(b => b.style.width = small ? '150px' : '');
    N.forEach(n => { const b = el(n.id), p = pos(n, W, b.offsetWidth); b.style.left = (p.x * W - b.offsetWidth / 2) + 'px'; b.style.top = (p.y * H - b.offsetHeight / 2) + 'px'; });
    wires();
  }
  // the wires are made once and only reshaped after that, so a resize or a drag never restarts their draw or their light
  const wireEl = {};
  function wires(){
    E.forEach(([a, b]) => { const A = el(a), B = el(b); const ax = A.offsetLeft + A.offsetWidth / 2, ay = A.offsetTop + A.offsetHeight / 2, bx = B.offsetLeft + B.offsetWidth / 2, by = B.offsetTop + B.offsetHeight / 2;
      let d; if (narrow()){ const y1 = ay + A.offsetHeight / 2, y2 = by - B.offsetHeight / 2; d = `M${ax} ${y1} C${ax} ${(y1 + y2) / 2} ${bx} ${(y1 + y2) / 2} ${bx} ${y2}`; }
      else { const x1 = ax + A.offsetWidth / 2, x2 = bx - B.offsetWidth / 2; d = `M${x1} ${ay} C${(x1 + x2) / 2} ${ay} ${(x1 + x2) / 2} ${by} ${x2} ${by}`; }
      let p = wireEl[a + b]; if (!p){ p = document.createElementNS('http://www.w3.org/2000/svg', 'path'); p.dataset.e = a + b; svg.appendChild(p); wireEl[a + b] = p; }
      p.setAttribute('d', d);
      if (svg.classList.contains('intro') && !p.style.getPropertyValue('--l')) p.style.setProperty('--l', Math.ceil(p.getTotalLength())); });
  }
  let selN = null;
  function config(n){
    const b = el(n.id); $$('.acx-n', nodes).forEach(x => x.classList.toggle('sel', x === b)); selN = n;
    pop.innerHTML = `<h4>${n.t}</h4><div class="acx-fl"><span>${n.f[0]}</span><button class="acx-dd"><span>${n.d}</span>${I('chev-d','xs')}</button><div class="acx-opts">${n.f[1].map(o => `<button class="mi" aria-checked="${o === n.d}"><span>${o}</span><span class="ck">${I('check','xs')}</span></button>`).join('')}</div></div><button class="pill soft sm acx-done">Done</button>`;
    const W = cv.clientWidth; let x = b.offsetLeft + b.offsetWidth + 10; if (x + 240 > W) x = b.offsetLeft - 250; if (x < 6) x = 6;
    let y = b.offsetTop - 40; y = Math.max(6, Math.min(y, cv.clientHeight - 190));
    pop.style.left = x + 'px'; pop.style.top = y + 'px'; pop.style.position = 'absolute'; pop.classList.add('open');
    const dd = $('.acx-dd', pop), ops = $('.acx-opts', pop);
    dd.onclick = e => { e.stopPropagation(); ops.classList.toggle('open'); };
    $$('.mi', ops).forEach(m => m.onclick = e => { e.stopPropagation(); n.d = $('span', m).textContent; swap($('.d', b), n.d); swap($('span', dd), n.d); $$('.mi', ops).forEach(x => x.setAttribute('aria-checked', x === m)); ops.classList.remove('open'); if (n.id === 't') swap(st, n.d.replace('Mondays', 'Every Monday,')); });
    $('.acx-done', pop).onclick = close;
  }
  function close(){ pop.classList.remove('open'); $$('.acx-n', nodes).forEach(x => x.classList.remove('sel')); selN = null; }
  let justDragged = false;
  N.forEach(n => {
    const b = el(n.id);
    b.onclick = e => { e.stopPropagation(); if (justDragged){ justDragged = false; return; } selN === n ? close() : config(n); };
    b.onpointerdown = e => {
      if (e.button) return; const sx = e.clientX, sy = e.clientY, ox = b.offsetLeft, oy = b.offsetTop; let moved = false;
      const mv = ev => { const dx = ev.clientX - sx, dy = ev.clientY - sy;
        if (!moved && Math.hypot(dx, dy) < 4) return;
        if (!moved){ moved = true; b.classList.add('drag'); close(); b.setPointerCapture?.(e.pointerId); }
        const W = cv.clientWidth, H = cv.clientHeight;
        b.style.left = Math.max(4, Math.min(W - b.offsetWidth - 4, ox + dx)) + 'px'; b.style.top = Math.max(4, Math.min(H - b.offsetHeight - 4, oy + dy)) + 'px'; wires(); };
      const up = () => { document.removeEventListener('pointermove', mv); document.removeEventListener('pointerup', up);
        if (!moved) return; b.classList.remove('drag'); justDragged = true; setTimeout(() => justDragged = false, 50);
        const f = { x:(b.offsetLeft + b.offsetWidth / 2) / cv.clientWidth, y:(b.offsetTop + b.offsetHeight / 2) / cv.clientHeight }; if (narrow()) n.um = f; else n.uw = f; };
      document.addEventListener('pointermove', mv); document.addEventListener('pointerup', up);
      c.offs.push(() => { document.removeEventListener('pointermove', mv); document.removeEventListener('pointerup', up); });
    };
  });
  c.on(cv, 'click', e => { if (!pop.contains(e.target)) close(); });
  pop.onclick = e => e.stopPropagation();
  // a step's badge pops in once (CSS), and after that its spinner turns into a check with a short crossfade
  const ease = getComputedStyle(r).getPropertyValue('--ease').trim() || 'ease';
  const mark = (id, s) => { const b = el(id); b.classList.toggle('run', s === 'run'); const x = $('.s', b) || b.appendChild(html('<span class="s"></span>'));
    x.innerHTML = `<span class="acx-sv">${s === 'run' ? '<span class="spin" style="width:10px;height:10px"></span>' : `<span style="color:var(--ok);display:grid">${I('check','xs')}</span>`}</span>`; };
  // a run passes along a wire as one soft light, then leaves the wire lit
  const flow = (a, b) => { const p = wireEl[a + b]; if (!p) return; p.classList.add('done'); if (REDUCE) return;
    const L = p.getTotalLength(), len = Math.min(64, L * .4), q = p.cloneNode(); q.removeAttribute('data-e'); q.setAttribute('class', 'pulse'); q.style.cssText = `stroke-dasharray:${len} ${L + len}`; svg.appendChild(q);
    q.animate([{ strokeDashoffset:len, opacity:0 }, { opacity:1, offset:.18 }, { opacity:1, offset:.78 }, { strokeDashoffset:-L, opacity:0 }], { duration:720, easing:'cubic-bezier(.45,0,.25,1)' }).onfinish = () => q.remove(); };
  // a new test run cancels one still in progress and starts over, rather than running alongside it
  let runId = 0;
  $('.acx-run', r).onclick = () => c.run(async () => {
    const id = ++runId, wait = async ms => { await c.wait(ms); if (id !== runId) throw 'stop'; };
    // the last run's badges and lit wires fade back before the new run starts
    close(); $$('.acx-n .s', nodes).forEach(x => { if (REDUCE) return x.remove(); x.animate([{ opacity:1 }, { opacity:0, transform:'scale(.7)' }], { duration:200, easing:ease }).onfinish = () => x.remove(); });
    $$('.acx-n.run', nodes).forEach(x => x.classList.remove('run')); $$('path.done', svg).forEach(x => x.classList.remove('done')); swap(st, 'Running test');
    await wait(220); mark('t', 'run'); await wait(600); mark('t', 'ok');
    flow('t','a'); flow('t','b'); await wait(620);
    mark('a', 'run'); mark('b', 'run'); await wait(1100); mark('a', 'ok'); await wait(400); mark('b', 'ok');
    flow('a','c'); flow('b','c'); await wait(620);
    mark('c', 'run'); await wait(700); mark('c', 'ok'); swap(st, 'Test passed in 3.4s');
  });
  svg.classList.add('intro'); c.later(1300, () => svg.classList.remove('intro'));
  layout(); let lw = 0; const ro = new ResizeObserver(() => { if (lw && Math.abs(cv.clientWidth - lw) > 2) close(); lw = cv.clientWidth; layout(); }); ro.observe(cv); c.offs.push(() => ro.disconnect());
  $$('.acx-n', nodes).forEach((b, i) => { b.classList.add('acx-in'); b.style.animationDelay = i * 90 + 'ms'; });
  // the preview runs one test on its own, unless you start moving steps around first
  let mine = false; c.on(r, 'pointerdown', e => { if (e.isTrusted) mine = true; }, true);
  c.later(1600, () => { if (!mine) $('.acx-run', r).click(); });
});
